// Copie para firebase-config.js e preencha com a configuração pública do seu projecto Firebase.
// A configuração web do Firebase não é uma credencial secreta; as regras e a autenticação são a segurança real.
// Nunca inclua service-account keys, tokens privados ou segredos do servidor no frontend.
export const firebaseConfig = {
  apiKey: "YOUR_FIREBASE_WEB_API_KEY",
  authDomain: "YOUR_PROJECT.firebaseapp.com",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_PROJECT.firebasestorage.app",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};
